import{c as o,$ as i,Q as r,j as s,g as a,o as n,n as c,m as l}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Backups & Data Security","description":"Automatic generation snapshots, manual export to ZIP and CSV, selective restoration, and database resilience in OmniCraft ERP.","frontmatter":{"title":"Backups & Data Security","description":"Automatic generation snapshots, manual export to ZIP and CSV, selective restoration, and database resilience in OmniCraft ERP.","order":17,"datePublished":"2026-11-14","dateModified":"2026-11-22"},"headers":[],"relativePath":"docs/backups.md","filePath":"docs/backups.md","lastUpdated":1795305600000}'),d={name:"docs/backups.md"},p={id:"backups-and-data-security",tabindex:"-1"};function u(h,e,m,g,f,b){const t=i("DocIcon");return r(),s("div",null,[a("h1",p,[n(t,{name:"database"}),e[0]||(e[0]=c(" Backups and Data Security ",-1)),e[1]||(e[1]=a("a",{class:"header-anchor",href:"#backups-and-data-security","aria-label":'Permalink to "Backups and Data Security"'},"​",-1))]),e[2]||(e[2]=l('<p>OmniCraft ERP is architected as sovereign, offline-first desktop software. Your database, bills of materials, cost formulas, and financial balances reside strictly on your local computer, eliminating data leaks to third-party cloud infrastructure.</p><p>Local data sovereignty guarantees uninterrupted operation without an internet connection, yet demands disciplined stewardship of your storage. To protect your business from drive crashes, ransomware, or operating system failures, the software features a multi-tiered automated and manual backup engine.</p><hr><h2 id="automatic-shadow-backups" tabindex="-1">Automatic Shadow Backups <a class="header-anchor" href="#automatic-shadow-backups" aria-label="Permalink to &quot;Automatic Shadow Backups&quot;">​</a></h2><p>In the background, the application executes a generational archive rotation strategy (Grandfather-Father-Son). Snapshot generation runs asynchronously, introducing zero user interface latency and never interrupting the craftsman&#39;s calculations.</p><h3 id="_1-startup-backups" tabindex="-1">1. Startup Backups <a class="header-anchor" href="#_1-startup-backups" aria-label="Permalink to &quot;1. Startup Backups&quot;">​</a></h3><p>Upon every launch, OmniCraft ERP inspects the system calendar. When a new accounting cycle begins, the engine packages a lightweight snapshot of the workspace ecosystem without media files:</p><ul><li><strong>Daily Snapshot</strong> (<code>auto_daily.zip</code>) — created upon the first application start of the current day.</li><li><strong>Weekly Snapshot</strong> (<code>auto_weekly.zip</code>) — records the state of your books at the beginning of each calendar week.</li><li><strong>Monthly Snapshot</strong> (<code>auto_monthly.zip</code>) — preserves a benchmark snapshot on the first day of every month.</li><li><strong>Yearly Snapshot</strong> (<code>auto_yearly.zip</code>) — long-term archive for annual financial reviews and tax preparation.</li></ul><h3 id="_2-application-shutdown-backups" tabindex="-1">2. Application Shutdown Backups <a class="header-anchor" href="#_2-application-shutdown-backups" aria-label="Permalink to &quot;2. Application Shutdown Backups&quot;">​</a></h3><p>When the craftsman exits the application, OmniCraft ERP immediately hides the main window and executes background maintenance:</p><ol><li><strong>Index Optimization:</strong> Runs the SQLite <code>PRAGMA optimize;</code> command, updating internal query planner statistics to accelerate subsequent lookups without blocking I/O.</li><li><strong>Three-Slot Rotational Cascade:</strong> The application maintains a sliding trio of recent session exits — <code>auto_close_1.zip</code>, <code>auto_close_2.zip</code>, and <code>auto_close_3.zip</code>. Each time the application closes, older snapshots shift back by one position, preserving access to your last three active sessions.</li><li><strong>Temporary Asset Cleanup:</strong> An automated garbage collector purges temporary HTML label preview files and thermal print buffers.</li></ol><h3 id="_3-preemptive-safety-snapshots" tabindex="-1">3. Preemptive Safety Snapshots <a class="header-anchor" href="#_3-preemptive-safety-snapshots" aria-label="Permalink to &quot;3. Preemptive Safety Snapshots&quot;">​</a></h3><p>Prior to executing any irreversible operational commands, the system forces an immediate shadow database backup:</p><ul><li>Before initiating an <strong>«Accounting Reset»</strong> (clearing operational ledgers);</li><li>Before executing a <strong>«Factory Reset»</strong>;</li><li>Before automatic database schema migrations when upgrading to a newer software release.</li></ul><h3 id="_4-backup-storage-directory" tabindex="-1">4. Backup Storage Directory <a class="header-anchor" href="#_4-backup-storage-directory" aria-label="Permalink to &quot;4. Backup Storage Directory&quot;">​</a></h3><p>All automated snapshots are stored in the application&#39;s secure operating system data path:</p><ul><li><strong>Windows:</strong> <code>%APPDATA%\\OmniCraft\\backups\\</code> (typically <code>C:\\Users\\&lt;User&gt;\\AppData\\Roaming\\OmniCraft\\backups\\</code>);</li><li><strong>Linux:</strong> <code>~/.config/OmniCraft/backups/</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Protecting Your Archive Directory</p><p>Configure automated synchronization between the local <code>backups</code> directory and an external drive or encrypted network share. In the event of catastrophic drive failure, you can restore your workshop in minutes.</p></div><hr><h2 id="manual-data-export" tabindex="-1">Manual Data Export <a class="header-anchor" href="#manual-data-export" aria-label="Permalink to &quot;Manual Data Export&quot;">​</a></h2><p>To migrate data to a new computer, share books with an accountant, or generate a permanent offsite archive, navigate to <strong>«File» ➔ «Export Data...»</strong>. The system provides two export formats.</p><h3 id="_1-full-system-backup-zip" tabindex="-1">1. Full System Backup (.zip) <a class="header-anchor" href="#_1-full-system-backup-zip" aria-label="Permalink to &quot;1. Full System Backup (.zip)&quot;">​</a></h3><p>Generates a compressed archive containing your entire workspace ecosystem. The modal export dialog allows craftsmen to selectively package specific components:</p><ul><li><code>[x] Core Accounting Data</code> — the primary <code>omnicraft_erp.db</code> database (raw materials, recipes, finished stock, orders, sales, and cash flow);</li><li><code>[x] Workspaces</code> — isolated personal capital databases (<code>workspaces/*.db</code>) and the system registry <code>workspaces.json</code>;</li><li><code>[x] Photos, Media and Tech Card Documents</code> — photos of raw materials, equipment and finished goods, plus files attached to tech cards;</li><li><code>[x] AI Knowledge Base &amp; Skills</code> — customized trade prompt manifest, learned rules, and specialized prompt templates;</li><li><code>[x] Chat History &amp; Projects</code> — assistant dialogue sessions stored in <code>ai_context.db</code>.</li></ul><p>Every generated archive automatically embeds a <code>backup_manifest.json</code> descriptor in its root, containing schema versioning, checksums, and component metadata.</p><div class="tip custom-block"><p class="custom-block-title">Fast Lightweight Exports</p><p>AI conversation logs are physically isolated within the dedicated <code>ai_context.db</code> database. Unchecking «Chat History &amp; Projects» significantly accelerates compression, generating a compact archive file well-suited for routine external storage.</p></div><h3 id="_2-active-workspace-tables-zip-with-csv" tabindex="-1">2. Active Workspace Tables (.zip with CSV) <a class="header-anchor" href="#_2-active-workspace-tables-zip-with-csv" aria-label="Permalink to &quot;2. Active Workspace Tables (.zip with CSV)&quot;">​</a></h3><p>Selecting <strong>«Current Workspace Tables (.zip with CSV)»</strong> generates an exhaustive dump of all database tables from the active workspace as discrete comma-separated text files bundled into a single ZIP archive.</p><ul><li><strong>Independent Financial Audits:</strong> CSV files open directly in spreadsheet suites (Excel, LibreOffice Calc, Google Sheets) for external reconciliations, custom pivot reporting, or data analysis.</li><li><strong>The Digital Parachute:</strong> If a binary database file ever suffers hardware-level block corruption and cannot be mounted, plain text CSV files can always be inspected in any text editor and restored line-by-line.</li></ul><hr><h2 id="data-restoration-and-rollback-procedures" tabindex="-1">Data Restoration and Rollback Procedures <a class="header-anchor" href="#data-restoration-and-rollback-procedures" aria-label="Permalink to &quot;Data Restoration and Rollback Procedures&quot;">​</a></h2><p>Recovery routines are accessed through the application menu via <strong>«File» ➔ «Import Data...»</strong> and <strong>«File» ➔ «Restore from Auto-backup...»</strong>.</p><h3 id="_1-restore-from-auto-backup-time-machine" tabindex="-1">1. Restore from Auto-Backup (Time Machine) <a class="header-anchor" href="#_1-restore-from-auto-backup-time-machine" aria-label="Permalink to &quot;1. Restore from Auto-Backup (Time Machine)&quot;">​</a></h3><p>Selecting <strong>«Restore from Auto-backup...»</strong> opens a chronological catalog of automated snapshots. Each recovery point is presented with its creation date, exact timestamp, and archive size:</p><ol><li>Select your target snapshot from the list («Program Exit (Latest)», «Daily Backup», or an archive from the preceding week);</li><li>Click the restore button and confirm the action in the prompt dialog;</li><li>The software unpacks the database, verifies integrity constraints, and performs a clean application reboot.</li></ol><h3 id="_2-selective-restoration-from-backup-archives" tabindex="-1">2. Selective Restoration from Backup Archives <a class="header-anchor" href="#_2-selective-restoration-from-backup-archives" aria-label="Permalink to &quot;2. Selective Restoration from Backup Archives&quot;">​</a></h3><p>Selecting <strong>«Restore System from Backup (.zip)»</strong> prompts the system to inspect the embedded <code>backup_manifest.json</code> file and display a selective restoration dialog:</p><ul><li>Craftsmen can restore only material stocks and recipe catalogs while leaving current AI chat histories intact;</li><li>You can selectively restore personal capital databases without modifying commercial workshop registries;</li><li>The built-in validator inspects schema compatibility and rejects corrupted or alien archive files.</li></ul><h3 id="_3-binary-database-replacement-db" tabindex="-1">3. Binary Database Replacement (.db) <a class="header-anchor" href="#_3-binary-database-replacement-db" aria-label="Permalink to &quot;3. Binary Database Replacement (.db)&quot;">​</a></h3><p>When supplying a raw SQLite database file with the <code>.db</code> extension (such as an exported <code>omnicraft_erp.db</code>), the system performs a safe file replacement, verifies table schemas, and reboots the application window cleanly.</p><h3 id="_4-workspace-tables-import-from-csv-archives" tabindex="-1">4. Workspace Tables Import from CSV Archives <a class="header-anchor" href="#_4-workspace-tables-import-from-csv-archives" aria-label="Permalink to &quot;4. Workspace Tables Import from CSV Archives&quot;">​</a></h3><p>Selecting <strong>«Import Workspace Tables (.zip with CSV)»</strong> instructs the system to unpack the CSV files, purge existing tables in the active workspace, and systematically stream the records back into the database. Each data stream undergoes strict type validation, preventing syntax errors and foreign key mismatches.</p><div class="danger custom-block"><p class="custom-block-title">Critical Rule: Imports Overwrite Existing Data</p><p>The restoration procedure <strong>does not merge</strong> records; it entirely replaces the current application state with the data from the backup file. Any transactions, sales, or configuration changes recorded after the creation date of the backup will be permanently lost. Always create a fresh manual export before restoring an older archive!</p></div><hr><h2 id="engineering-reliability-under-the-hood" tabindex="-1">Engineering Reliability Under the Hood <a class="header-anchor" href="#engineering-reliability-under-the-hood" aria-label="Permalink to &quot;Engineering Reliability Under the Hood&quot;">​</a></h2><p>Beyond scheduled backups, the OmniCraft ERP storage engine is engineered from the ground up to withstand sudden power outages and host system instability.</p><h3 id="_1-write-ahead-logging-wal-mode" tabindex="-1">1. Write-Ahead Logging (WAL Mode) <a class="header-anchor" href="#_1-write-ahead-logging-wal-mode" aria-label="Permalink to &quot;1. Write-Ahead Logging (WAL Mode)&quot;">​</a></h3><p>All databases in the application operate under SQLite Write-Ahead Logging mode:</p><ul><li>Any data mutation (recording a purchase order, logging a sale, or deducting materials) is first written atomically to a dedicated write-ahead log file.</li><li>Only after the log entry is safely flushed to the physical drive are changes committed to the primary database file.</li><li><strong>Surviving Workshop Power Failures:</strong> If electrical power cuts out while a craftsman is recording a transaction, database corruption is prevented. Upon subsequent launch, SQLite automatically reads the log and either completes the commit or rolls it back cleanly to a valid state.</li></ul><h3 id="_2-atomic-file-replacement-and-i-o-mutex" tabindex="-1">2. Atomic File Replacement and I/O Mutex <a class="header-anchor" href="#_2-atomic-file-replacement-and-i-o-mutex" aria-label="Permalink to &quot;2. Atomic File Replacement and I/O Mutex&quot;">​</a></h3><p>When background snapshots are generated, the engine protects the live database from concurrency conflicts:</p><ul><li>Background operations synchronize through the file I/O mutex (<code>WORKSPACE_IO_MUTEX</code>), preventing simultaneous database writes during archive creation.</li><li>Snapshots are compiled into a temporary <code>.tmp</code> file and only swapped into the target path upon successful compression using the atomic system call <code>os.replace</code>.</li></ul><h3 id="_3-multi-threaded-concurrency-and-deadlock-protection" tabindex="-1">3. Multi-Threaded Concurrency and Deadlock Protection <a class="header-anchor" href="#_3-multi-threaded-concurrency-and-deadlock-protection" aria-label="Permalink to &quot;3. Multi-Threaded Concurrency and Deadlock Protection&quot;">​</a></h3><p>To eliminate lock contention between the user interface, background collectors, and AI assistant workers, the core applies robust database pragmas:</p><ul><li>The connection busy timeout is extended to 5,000 milliseconds (<code>PRAGMA busy_timeout = 5000;</code>);</li><li>Strict relational integrity is enforced via <code>PRAGMA foreign_keys = ON;</code>;</li><li>Disk synchronization uses <code>PRAGMA synchronous = NORMAL;</code>, achieving a robust balance between throughput and physical durability.</li></ul><hr><h2 id="workshop-data-protection-standards" tabindex="-1">Workshop Data Protection Standards <a class="header-anchor" href="#workshop-data-protection-standards" aria-label="Permalink to &quot;Workshop Data Protection Standards&quot;">​</a></h2><p>To ensure total security of your business records, adopt two fundamental operational habits:</p><h3 id="_1-the-3-2-1-backup-strategy-in-practice" tabindex="-1">1. The 3-2-1 Backup Strategy in Practice <a class="header-anchor" href="#_1-the-3-2-1-backup-strategy-in-practice" aria-label="Permalink to &quot;1. The 3-2-1 Backup Strategy in Practice&quot;">​</a></h3><ul><li><strong>3 Copies of Data:</strong> Primary working database on your computer + automated snapshots in the application directory + regular manual offsite exports.</li><li><strong>2 Different Media Types:</strong> Your workstation&#39;s internal solid-state drive + an external portable drive or USB memory key.</li><li><strong>1 Remote Copy:</strong> An encrypted full system backup ZIP file uploaded to trusted cloud storage or a dedicated home server.</li></ul><h3 id="_2-migrating-to-a-new-workstation-in-3-minutes" tabindex="-1">2. Migrating to a New Workstation in 3 Minutes <a class="header-anchor" href="#_2-migrating-to-a-new-workstation-in-3-minutes" aria-label="Permalink to &quot;2. Migrating to a New Workstation in 3 Minutes&quot;">​</a></h3><p>To transfer your entire workshop to a new computer without data loss:</p><ol><li>On the old machine, open <strong>«File» ➔ «Export Data...» ➔ «Full System Backup (.zip)»</strong> and select all components;</li><li>Save the archive to a portable drive;</li><li>Install OmniCraft ERP on the new computer and launch the clean program;</li><li>Select <strong>«File» ➔ «Import Data...» ➔ «Restore System from Backup (.zip)»</strong> and choose your archive file;</li><li>The application restores all workspaces, inventory, recipes, photos, and settings, rebooting immediately into your fully configured production environment.</li></ol><hr><h2 id="troubleshooting-common-backup-issues" tabindex="-1">Troubleshooting &amp; Common Backup Issues <a class="header-anchor" href="#troubleshooting-common-backup-issues" aria-label="Permalink to &quot;Troubleshooting &amp; Common Backup Issues&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">What should I do if the application reports an access error for the backup directory?</summary><div class="faq-content"><p>This is typically caused by third-party antivirus software locking the directory or insufficient write permissions for <code>%APPDATA%\\OmniCraft\\backups\\</code>. Verify sufficient free disk space on your primary drive C:, add the OmniCraft application folder to your antivirus whitelist, and restart OmniCraft ERP under your standard user account (administrative elevation is not required).</p></div></details><details class="faq-item"><summary class="faq-summary">How can I recover my data if an external ZIP backup was corrupted during copy?</summary><div class="faq-content"><p>If an external archive cannot be opened due to a faulty USB flash drive, use the built-in menu item <b>«File» ➔ «Restore from Autosave...»</b>. The system maintains a sliding trio of recent session shutdowns (<code>auto_close_1.zip</code> through <code>auto_close_3.zip</code>) alongside daily snapshots. Select a recovery point from the previous business day to roll back state safely.</p></div></details><details class="faq-item"><summary class="faq-summary">What happens when restoring a backup created on an older software release?</summary><div class="faq-content"><p>During restore, the database engine verifies the schema version in <code>backup_manifest.json</code>. If the archive originated from an earlier release of OmniCraft ERP, the built-in migration engine automatically executes missing schema updates. Conversely, if the archive belongs to a newer version than currently installed, the software warns you to upgrade the application first to prevent database structure corruption.</p></div></details></div>',66))])}const v=o(d,[["render",u]]);export{k as __pageData,v as default};
